-- Buat tabel jika belum ada
CREATE TABLE IF NOT EXISTS pekerja_pak (
    id SERIAL PRIMARY KEY,
    tanggal_update DATE,
    nama VARCHAR(255),
    jenis_kelamin VARCHAR(50),
    status_pekerjaan VARCHAR(100),
    tempat_kerja VARCHAR(255),
    kota_kab VARCHAR(100),
    dugaan_pajanan VARCHAR(255),
    bekerja_sejak DATE,
    bekerja_sampai DATE,
    diagnosis_terakhir TEXT,
    status_advokasi VARCHAR(255),
    tantangan TEXT,
    status_penetapan_pak VARCHAR(255)
);

